const ProjectArchive = ({ projects = [] }) => {
  if (!projects.length) return null;
  return (
    <section className="archive-section" aria-labelledby="archive-title">
      <div className="section-heading"><h2 id="archive-title">Earlier explorations.</h2><p className="eyebrow">2019–2022 / Archive</p></div>
      {projects.map(project => (
        <div key={project.title} className="archive-row">
          <span className="eyebrow">{project.year}</span>
          <div><h3>{project.title}</h3><p>{project.summary}</p></div>
        </div>
      ))}
    </section>
  );
};

export default ProjectArchive;
